using namespace std;
​
int main() {
    int n,m;
    cin >> n >> m;
​
    vector<int> free(n+1, 0);
    for (int i = 1; i <= n; i++) {
        cin >> free[i];
    }
    // 记录每一次分配的id 和 大小
    vector<pair<int, int>> alloc;
​
    vector<int> result;
​
    while (m--) {
        int type, x;
        cin >> type >> x;
        // 分配
        if (type == 1) {
           int bestID = 0;
           int bestRemoveFree = INT_MAX;
           for (int i = 1; i <= n; i++) {
               // 无法满足分配
               if (free[i] < x) {
                continue;
               }
               int rem = free[i] - x;
               if (bestID == 0|| bestRemoveFree > rem) {
                  bestID = i;
                  bestRemoveFree = rem;  
               }
            }
            // 分配失败
            if (bestID == 0) {
                alloc.push_back({0, 0});
            } else {
                free[bestID] -= x;
                alloc.push_back({bestID, x});
            }
            result.push_back(bestID); 
        } else { // 释放
            // 输入数据有问题
            if (x > alloc.size()) {
                continue;
            }
            pair<int, int> p = alloc[x -1];
            // 没有分配成功
            if (p.first == 0) {
                continue;
            }
            free[p.first] += p.second;
        }
    }
​
    // 输出结果
    for (int i = 0; i < result.size(); i++) {
        cout << result[i];
        if (i != result.size() - 1) {
            cout << " ";
        }
    }
    return 0;
}
