        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
​
        // 存储每个节点的空闲内存
        int[] free = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            free[i] = sc.nextInt();
        }
​
        // 记录每一次分配的id 和 大小
        List<int[]> alloc = new ArrayList<>();
        List<Integer> result = new ArrayList<>();
​
        while (m-- > 0) {
            int type = sc.nextInt();
            int x = sc.nextInt();
​
            if (type == 1) {
                // 分配内存
                int bestID = 0;
                int bestRemoveFree = Integer.MAX_VALUE;
                for (int i = 1; i <= n; i++) {
                    // 无法满足分配
                    if (free[i] < x) continue;
                    int rem = free[i] - x;
                    if (bestID == 0 || bestRemoveFree > rem) {
                        bestID = i;
                        bestRemoveFree = rem;
                    }
                }
                // 分配失败
                if (bestID == 0) {
                    alloc.add(new int[]{0, 0});
                } else {
                    free[bestID] -= x;
                    alloc.add(new int[]{bestID, x});
                }
                result.add(bestID);
            } else {
                // 释放内存
                if (x > alloc.size()) continue;
                int[] p = alloc.get(x - 1);
                // 没有分配成功
                if (p[0] == 0) continue;
                free[p[0]] += p[1];
            }
        }
​
