package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    reader := bufio.NewReader(os.Stdin)
​
    line1, _ := reader.ReadString('\n')
    nm := strings.Fields(line1)
    n, _ := strconv.Atoi(nm[0])
    m, _ := strconv.Atoi(nm[1])
​
    line2, _ := reader.ReadString('\n')
    nums := strings.Fields(line2)
    // 存储每个节点的空闲内存
    free := make([]int, n+1)
    for i := 1; i <= n; i++ {
        free[i], _ = strconv.Atoi(nums[i-1])
    }
​
    // 记录每一次分配的id 和 大小
    var alloc [][2]int
    var result []int
​
    for i := 0; i < m; i++ {
        line, _ := reader.ReadString('\n')
        parts := strings.Fields(line)
        if len(parts) < 2 {
            continue
        }
        typ, _ := strconv.Atoi(parts[0])
        x, _ := strconv.Atoi(parts[1])
​
        if typ == 1 {
            // 分配内存
            bestID := 0
            bestRemoveFree := 1 << 30
            for j := 1; j <= n; j++ {
                // 无法满足分配
                if free[j] < x {
                    continue
                }
                rem := free[j] - x
                if bestID == 0 || bestRemoveFree > rem {
                    bestID = j
                    bestRemoveFree = rem
                }
            }
            // 分配失败
            if bestID == 0 {
                alloc = append(alloc, [2]int{0, 0})
            } else {
                free[bestID] -= x
                alloc = append(alloc, [2]int{bestID, x})
            }
            result = append(result, bestID)
        } else {
            // 释放内存
            if x > len(alloc) {
                continue
            }
            p := alloc[x-1]
            // 没有分配成功
            if p[0] == 0 {
                continue
            }
            free[p[0]] += p[1]
        }
    }
​
    // 输出结果
    for i, v := range result {
        if i > 0 {
            fmt.Print(" ")
        }
        fmt.Print(v)
    }
}
